/* Study OS — local-first study command centre */
(() => {
  'use strict';
  const KEY='study-os-v1';
  const blank=()=>({goals:[],tasks:[],backlogs:[],events:[],revisions:[],exams:[],notes:[],journals:[],sessions:[],settings:{name:'Student',target:4,focus:25,shortBreak:5,longBreak:15,subjects:[],weekStart:'Monday',volume:35,notifications:false},music:{kind:'ambient',track:'Rainy Focus',playing:false,volume:35},streak:0,lastStudyDate:''});
  let db=blank();
  try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved==='object')db={...blank(),...saved,settings:{...blank().settings,...saved.settings},music:{...blank().music,...saved.music}};}catch{localStorage.removeItem(KEY);}
  // A Web Audio graph and a File object URL cannot survive a reload; never report stale playback.
  db.music.playing=false;
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const dateKey=(d=new Date())=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;};
  const fmtDate=(x,opts={month:'short',day:'numeric'})=>x?new Date(`${x}T12:00:00`).toLocaleDateString(undefined,opts):'No date';
  const uid=()=>Math.random().toString(36).slice(2,10), today=dateKey(), dayName=new Date().toLocaleDateString(undefined,{weekday:'long'});
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(db));}catch{toast('Could not save. Browser storage may be full.',true);}syncProfile();};
  const syncProfile=()=>{$('#profile-name').textContent=db.settings.name||'Student';$('#avatar').textContent=(db.settings.name||'S')[0].toUpperCase();$$('.small-avatar').forEach(x=>x.textContent=(db.settings.name||'S')[0].toUpperCase());$('#streak-value').textContent=`${db.streak||0} day streak`;$('#task-count').textContent=db.tasks.filter(x=>x.status!=='Completed').length+db.backlogs.filter(x=>x.progress<100).length;};
  let toastTimer;function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.classList.toggle('error',error);t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600);}
  const titleCase=s=>s.replace(/\b\w/g,c=>c.toUpperCase());
  const pageNames={dashboard:'Dashboard',goals:'Daily goals',tasks:'Tasks & backlogs',timetable:'Timetable',revision:'Revision planner',exams:'Exams',focus:'Focus mode',music:'Music studio',notes:'Notes & resources',journal:'Daily journal',analytics:'Analytics',settings:'Settings','data':'Data & sync',report:'Report an issue',developer:'Developer’s insight'};
  let currentPage='dashboard';
  function route(){let p=location.hash.slice(1)||'dashboard';if(!pageNames[p])p='dashboard';currentPage=p;$('#page-crumb').textContent=pageNames[p];$$('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===p));render();$('#sidebar').classList.remove('open');}
  const header=(title,sub,action='')=>`<div class="page-head"><div><p class="eyebrow">${esc(title.toUpperCase())}</p><h1>${esc(title)}</h1><p>${sub}</p></div>${action}</div>`;
  const addBtn=(type,label='＋ Add new')=>`<button class="button primary" data-add="${type}">${label}</button>`;
  const empty=(title,detail,button='')=>`<div class="empty"><strong>${title}</strong>${detail}${button?`<div style="margin-top:12px">${button}</div>`:''}</div>`;
  const rows=(items,type,emptyText='Nothing here yet')=>items.length?`<div class="list">${items.map(x=>`<div class="list-row"><button class="check ${x.status==='Completed'||x.done?'done':''}" data-toggle="${type}" data-id="${x.id}" aria-label="Mark complete">${x.status==='Completed'||x.done?'✓':''}</button><div class="row-main"><strong>${esc(x.title||x.topic||x.name)}</strong><small>${esc(x.subject||x.category||type)}${x.due?' · Due '+fmtDate(x.due):x.date?' · '+fmtDate(x.date):''}</small></div><span class="tag ${x.priority==='High'?'amber':''}">${esc(x.priority||x.status||'Planned')}</span><button class="icon-button" data-edit="${type}" data-id="${x.id}" aria-label="Edit">✎</button><button class="icon-button danger" data-delete="${type}" data-id="${x.id}" aria-label="Delete">×</button></div>`).join('')}</div>`:empty(emptyText,'Your items will appear here.',addBtn(type));
  function suggestion(){const now=Date.now();let candidates=[];db.revisions.filter(x=>x.nextDate<=today).forEach(x=>candidates.push({title:`Revise ${x.topic}`,why:`${x.subject} · due for review`,type:'revision',item:x}));db.tasks.filter(x=>x.status!=='Completed').forEach(x=>candidates.push({title:x.title,why:`${x.priority||'Normal'} priority${x.due&&x.due<today?' · overdue':''} · ${x.estimate||30} min`,type:'task',item:x}));db.backlogs.filter(x=>x.progress<100).forEach(x=>candidates.push({title:`Make progress on ${x.topic}`,why:`${x.subject} · ${x.hours||1}h remaining · backlog`,type:'backlog',item:x}));candidates.sort((a,b)=>{let score=x=>((x.item.priority==='High'?5:x.item.priority==='Medium'?3:1)+(x.item.due&&x.item.due<today?8:0)+(x.item.nextDate&&x.item.nextDate<=today?9:0)+(x.item.due?Math.max(0,4-(new Date(x.item.due+'T12:00').getTime()-now)/86400000):0));return score(b)-score(a)});return candidates[0];}
  function dashboard(){const todaysGoals=db.goals.filter(x=>x.date===today),completed=todaysGoals.filter(x=>x.status==='Completed').length,pct=todaysGoals.length?Math.round(completed/todaysGoals.length*100):0;const seconds=db.sessions.filter(x=>x.date===today).reduce((s,x)=>s+x.minutes*60,0),mins=Math.floor(seconds/60),doneTasks=db.tasks.filter(x=>x.status==='Completed').length,open=db.tasks.filter(x=>x.status!=='Completed').length;const exam=db.exams.filter(x=>x.date>=today).sort((a,b)=>a.date.localeCompare(b.date))[0];const suggest=suggestion();const upcoming=db.events.filter(x=>x.day===dayName).sort((a,b)=>a.start.localeCompare(b.start));return `${header('Your study space',`${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})} · A little progress adds up.`,addBtn('goal','＋ New goal'))}<section class="dashboard-grid">
    <div class="card welcome"><p class="eyebrow">${esc(dayName.toUpperCase())} · ${fmtDate(today,{month:'long',day:'numeric',year:'numeric'})}</p><h1>${greeting()}, ${esc(db.settings.name||'Student')} <span style="color:#f3bd72">✦</span></h1><p>Ready to make today count? Take it one focused session at a time.</p><div class="welcome-bottom"><span><strong>${mins>=60?`${Math.floor(mins/60)}h ${mins%60}m`:`${mins}m`}</strong> studied today</span><span><strong>${doneTasks}</strong> tasks completed</span><span><strong>${db.streak||0}</strong> day streak</span></div></div>
    <div class="card score-card"><div class="card-title">Today's goals <span class="muted" style="float:right">${completed} of ${todaysGoals.length}</span></div><div class="score-main"><div class="ring" style="--progress:${pct}%"><span>${pct}%</span></div><div class="score-copy"><strong>${completed}<span style="color:#777;font-size:14px"> / ${todaysGoals.length}</span></strong><small>${todaysGoals.length?`${todaysGoals.length-completed} goals to go`:'Add a goal to get started'}</small></div></div></div>
    <div class="card stat"><div class="stat-top">Focus time <span class="stat-icon">◷</span></div><strong>${mins>=60?`${Math.floor(mins/60)}h ${mins%60}m`:`${mins}m`}</strong><small class="positive">Tracked from focus sessions</small></div>
    <div class="card stat"><div class="stat-top">Open tasks <span class="stat-icon">☷</span></div><strong>${open}</strong><small>${doneTasks} completed all time</small></div>
    <div class="card stat"><div class="stat-top">Active backlogs <span class="stat-icon">▤</span></div><strong>${db.backlogs.filter(x=>x.progress<100).length}</strong><small>${db.backlogs.filter(x=>x.progress<100).reduce((s,x)=>s+Number(x.hours||0)*(1-(x.progress||0)/100),0).toFixed(1)}h remaining</small></div>
    <div class="card stat"><div class="stat-top">Next exam <span class="stat-icon">▧</span></div><strong>${exam?Math.max(0,Math.ceil((new Date(exam.date+'T00:00:00')-new Date(today+'T00:00:00'))/86400000))+'d':'—'}</strong><small>${exam?esc(exam.name)+' · '+fmtDate(exam.date):'No upcoming exams'}</small></div>
    <div class="card section-card"><div class="card-heading"><h2>Today's goals</h2><a href="#goals" class="text-link">View all →</a></div>${rows(todaysGoals,'goal','No goals planned for today')}</div>
    <div class="card section-card narrow"><div class="card-heading"><h2>Today's schedule</h2><a href="#timetable" class="text-link">Timetable →</a></div>${upcoming.length?upcoming.slice(0,4).map(e=>`<div class="agenda-row"><time>${esc(e.start)}</time><i class="agenda-bar ${e.type==='Break'?'green':e.type==='Coaching'?'amber':e.type==='School'?'blue':''}"></i><div><strong>${esc(e.title)}</strong><small>${esc(e.subject||e.type)} · ${esc(e.end)}</small></div></div>`).join(''):empty('Nothing scheduled today','Add weekly sessions to your timetable.',addBtn('event','＋ Add session'))}</div>
    <div class="card mini-timer"><div class="timer-face"><strong id="dash-clock">${timerText()}</strong></div><div class="timer-info"><p class="eyebrow">FOCUS TIMER</p><h2 id="dash-timer-label">${timer.running?'Focus session':`${db.settings.focus} min focus`}</h2><p>A little focus goes a long way.<br>Your sessions are tracked automatically.</p><div class="timer-actions"><button class="button primary small" id="timer-main">${timer.running?'Pause':'Start focus'}</button><button class="button ghost small" id="timer-reset">Reset</button></div></div></div>
    <div class="card music-card"><div class="album-art">♫</div><div class="music-info"><p class="eyebrow">NOW PLAYING</p><h2>${esc(db.music.track||'Rainy Focus')}</h2><p>${db.music.kind==='local'?'Your music library':'Ambient soundscape · Web Audio'}</p><div class="music-controls"><button class="play-button" id="dash-music">${db.music.playing?'Ⅱ':'▶'}</button><div class="wave ${db.music.playing?'playing':''}">${'<i></i>'.repeat(9)}</div><button class="button ghost small" onclick="location.hash='#music'">Open studio →</button></div></div></div>
    <div class="card suggestion"><div class="suggest-icon">✦</div><div class="suggest-body"><strong>${suggest?`Try next: ${esc(suggest.title)}`:'Your next step starts here'}</strong><small>${suggest?esc(suggest.why):'Add a goal or task and Study OS will suggest a useful next step.'}</small></div>${suggest?`<button class="button secondary small" data-suggest="${suggest.type}" data-id="${suggest.item.id}">Add to today</button>`:addBtn('task','＋ Add a task')}</div>
    </section>`;}
  function greeting(){let h=new Date().getHours();return h<12?'Good morning':h<18?'Good afternoon':'Good evening';}
  let timer={running:false,mode:'Focus',remaining:db.settings.focus*60,total:db.settings.focus*60,interval:null,endAt:0};
  function timerText(){const sec=timer.remaining;return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
  function tick(){if(!timer.running)return;timer.remaining=Math.max(0,Math.ceil((timer.endAt-Date.now())/1000));if(timer.remaining<=0)finishTimer();updateClock();}
  function updateClock(){const text=timerText();const a=$('#dash-clock'),b=$('#focus-clock');if(a)a.textContent=text;if(b)b.textContent=text;const bar=$('#focus-progress');if(bar)bar.style.width=`${(1-timer.remaining/timer.total)*100}%`;const label=$('#focus-label');if(label)label.textContent=timer.mode;const btn=$('#timer-main');if(btn)btn.textContent=timer.running?'Pause':'Start focus';const fb=$('#focus-toggle');if(fb)fb.textContent=timer.running?'Pause':'Start focus';const mini=$('#mini-toggle');if(mini)mini.textContent=timer.running?'Ⅱ':'▶';}
  function startTimer(){if(timer.remaining<=0)resetTimer();timer.running=true;timer.endAt=Date.now()+timer.remaining*1000;clearInterval(timer.interval);timer.interval=setInterval(tick,250);tick();save();}
  function pauseTimer(){timer.running=false;clearInterval(timer.interval);save();updateClock();}
  function resetTimer(){timer.running=false;clearInterval(timer.interval);timer.remaining=timer.total;save();updateClock();}
  function setPreset(label,mins){pauseTimer();timer.mode=label;timer.total=mins*60;timer.remaining=timer.total;updateClock();if(currentPage==='focus')render();}
  function finishTimer(){clearInterval(timer.interval);timer.running=false;const mins=Math.max(1,Math.round(timer.total/60));if(timer.mode==='Focus'){db.sessions.push({id:uid(),date:today,minutes:mins,mode:'Focus',completedAt:new Date().toISOString()});if(db.streak===0||db.lastStudyDate!==today){const y=new Date();y.setDate(y.getDate()-1);db.streak=db.lastStudyDate===dateKey(y)?db.streak+1:1;db.lastStudyDate=today;}save();}timer.remaining=0;updateClock();try{if(db.settings.notifications&&Notification.permission==='granted')new Notification('Study OS',{body:`${timer.mode} session complete.`});}catch{}try{const C=window.AudioContext||window.webkitAudioContext;if(C){const c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=540;g.gain.value=.07;o.connect(g);g.connect(c.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.7);o.stop(c.currentTime+.7);setTimeout(()=>c.close(),1000);}}catch{}toast(`${timer.mode} session complete${timer.mode==='Focus'?` · ${mins} minutes tracked`:''}`);if(currentPage==='focus')render();}
  function goalsPage(){let list=db.goals.filter(x=>(!$('#goal-date-filter')?.value||x.date===$('#goal-date-filter').value)&&(!$('#goal-filter')?.value||x.status===$('#goal-filter').value));return `${header('Daily goals','Set an intention for your study day.',addBtn('goal','＋ Add goal'))}<div class="toolbar"><input class="field" type="date" id="goal-date-filter" value="${today}"><select class="field" id="goal-filter"><option value="">All statuses</option>${['Not Started','In Progress','Completed'].map(x=>`<option>${x}</option>`).join('')}</select><select class="field" id="goal-sort"><option value="date">Sort: date</option><option value="priority">Sort: priority</option><option value="created">Sort: recently added</option></select></div><div class="card">${rows(list,'goal','No goals match this view')}</div>`;}
  function tasksPage(){return `${header('Tasks & backlogs','Keep small tasks moving and make bigger backlogs manageable.',addBtn('task','＋ Add task')+' <button class="button secondary" data-add="backlog">＋ Add backlog</button>')}<div class="page-grid"><section class="card"><div class="card-heading"><h2>Tasks</h2><select class="field" id="task-filter"><option value="">All tasks</option>${['To Do','In Progress','Completed','Deferred'].map(x=>`<option>${x}</option>`).join('')}</select></div><div id="task-list">${taskTable()}</div></section><section class="card"><div class="card-heading"><h2>Backlog overview</h2><span class="tag">${db.backlogs.filter(x=>x.progress<100).reduce((s,x)=>s+Number(x.hours||0)*(1-(x.progress||0)/100),0).toFixed(1)}h remaining</span></div>${backlogList()}</section><section class="card full"><div class="card-heading"><h2>Break down a backlog</h2><span class="muted">Turn a large topic into a daily goal</span></div><div class="toolbar"><select class="field" id="backlog-select"><option value="">Choose a backlog item…</option>${db.backlogs.map(x=>`<option value="${x.id}">${esc(x.subject)} · ${esc(x.topic)}</option>`).join('')}</select><input class="field" id="break-parts" type="number" min="1" max="20" value="3" style="width:90px"><button class="button secondary" id="break-backlog">Create goals</button></div></section></div>`;}
  function taskTable(){let items=db.tasks.filter(x=>!$('#task-filter')?.value||x.status===$('#task-filter').value);if(!items.length)return empty('No tasks here yet','Add a task to keep it on your radar.',addBtn('task','＋ Add task'));return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Task</th><th>Subject</th><th>Due</th><th>Priority</th><th>Status</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td><span class="entry-title">${esc(x.title)}</span><div class="muted" style="margin-top:3px">${esc(x.category||'Other')}</div></td><td>${esc(x.subject||'—')}</td><td>${fmtDate(x.due)}</td><td><span class="tag ${x.priority==='High'?'amber':''}">${esc(x.priority||'Normal')}</span></td><td><select class="field task-status" data-id="${x.id}">${['To Do','In Progress','Completed','Deferred'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="icon-button" data-edit="task" data-id="${x.id}">✎</button><button class="icon-button danger" data-delete="task" data-id="${x.id}">×</button></td></tr>`).join('')}</tbody></table></div>`;}
  function backlogList(){return db.backlogs.length?db.backlogs.map(x=>`<div class="list-row"><div class="row-main"><strong>${esc(x.subject)} · ${esc(x.topic)}</strong><small>${esc(x.type||'Chapter')} · ${x.hours||0}h estimated${x.due?' · target '+fmtDate(x.due):''}</small><div class="task-meter"><span style="width:${Math.min(100,Math.max(0,x.progress||0))}%"></span></div></div><input class="field backlog-progress" data-id="${x.id}" type="number" min="0" max="100" value="${x.progress||0}" style="width:63px;padding:6px"><button class="icon-button" data-edit="backlog" data-id="${x.id}" title="Edit">✎</button><button class="icon-button" data-convert="${x.id}" title="Convert to goal">↗</button><button class="icon-button danger" data-delete="backlog" data-id="${x.id}">×</button></div>`).join(''):empty('No backlogs yet','Track larger unfinished topics separately.',addBtn('backlog','＋ Add backlog'));}
  function timetablePage(){const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];return `${header('Timetable','A weekly view of the time you have planned.',addBtn('event','＋ Add session'))}<div class="card"><div class="week-strip">${days.map(d=>`<button class="day-chip ${d===dayName?'active':''}" data-day="${d}"><strong>${d.slice(0,3)}</strong>${db.events.filter(e=>e.day===d).length} items</button>`).join('')}</div><div id="agenda">${agenda(dayName)}</div></div>`;}
  function agenda(day){const items=db.events.filter(e=>e.day===day).sort((a,b)=>a.start.localeCompare(b.start));return items.length?items.map((e,i)=>`<div class="agenda-row"><time>${esc(e.start)}</time><i class="agenda-bar ${e.type==='Break'?'green':e.type==='Coaching'?'amber':e.type==='School'?'blue':''}"></i><div><strong>${esc(e.title)}</strong><small>${esc(e.subject||e.type)} · ${esc(e.start)}–${esc(e.end)}${e.location?' · '+esc(e.location):''}</small></div><button class="icon-button danger" data-delete="event" data-id="${e.id}">×</button><button class="icon-button" data-edit="event" data-id="${e.id}">✎</button></div>`).join(''):empty('A clear day','Add recurring weekly sessions when you are ready.',addBtn('event','＋ Add session'));}
  function revisionPage(){const due=db.revisions.filter(x=>x.nextDate<=today),upcoming=db.revisions.filter(x=>x.nextDate>today);return `${header('Revision planner','Space reviews over time to make learning stick.',addBtn('revision','＋ Add topic'))}<div class="page-grid"><section class="card"><div class="card-heading"><h2>Due for review</h2><span class="tag amber">${due.length} due</span></div>${rows(due,'revision','No revisions due today')}</section><section class="card"><div class="card-heading"><h2>Coming up</h2></div>${upcoming.length?rows(upcoming,'revision','No upcoming revisions'):empty('Nothing scheduled','Add a studied topic to plan its next review.',addBtn('revision'))}</section><section class="card full"><div class="card-heading"><h2>All revision topics</h2><span class="muted">Completion schedules the next interval</span></div>${db.revisions.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Topic</th><th>Subject</th><th>Last studied</th><th>Next review</th><th>Difficulty</th><th></th></tr></thead><tbody>${db.revisions.map(x=>`<tr><td>${esc(x.topic)}</td><td>${esc(x.subject)}</td><td>${fmtDate(x.lastStudied)}</td><td>${fmtDate(x.nextDate)}</td><td>${'★'.repeat(Number(x.difficulty||1))}${'☆'.repeat(5-Number(x.difficulty||1))}</td><td><button class="icon-button" data-edit="revision" data-id="${x.id}">✎</button><button class="icon-button danger" data-delete="revision" data-id="${x.id}">×</button></td></tr>`).join('')}</tbody></table></div>`:empty('No topics yet','Build a spaced revision plan.',addBtn('revision'))}</section></div>`;}
  function examsPage(){const exams=[...db.exams].sort((a,b)=>a.date.localeCompare(b.date));return `${header('Exams','Keep the next milestone visible and plan your preparation.',addBtn('exam','＋ Add exam'))}<div class="page-grid">${exams.length?exams.map(x=>{let days=Math.ceil((new Date(x.date+'T00:00:00')-new Date(today+'T00:00:00'))/86400000),topics=(x.topics||'').split(',').filter(Boolean),done=x.doneTopics||[];return `<article class="card"><div class="card-heading"><span class="tag">${esc(x.subject||'Exam')}</span><button class="icon-button danger" data-delete="exam" data-id="${x.id}">×</button></div><h2 style="font:600 15px var(--display);margin:7px 0">${esc(x.name)}</h2><p class="muted" style="font-size:10px">${fmtDate(x.date,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}${x.time?' · '+esc(x.time):''}</p><div style="display:flex;align-items:baseline;gap:6px;margin:19px 0"><strong style="font:700 31px var(--display);color:${days<8?'#f3bd72':'#c5aeff'}">${days<0?'Past':days===0?'Today':days}</strong><span class="muted" style="font-size:10px">${days<0?'exam date passed':days===0?'exam day':'days remaining'}</span></div>${topics.length?`<div class="card-title">Syllabus · ${Math.round(done.length/topics.length*100)}%</div>${topics.map(t=>`<label class="list-row" style="padding:6px 0"><input type="checkbox" data-exam-topic="${x.id}" data-topic="${esc(t.trim())}" ${done.includes(t.trim())?'checked':''}><span style="font-size:10px">${esc(t.trim())}</span></label>`).join('')}`:''}<p class="muted" style="font-size:10px;line-height:1.5">${esc(x.notes||'')}</p></article>`}).join(''):empty('No exams added','Your exam dates and syllabus progress will show here.',addBtn('exam','＋ Add exam'))}</div>`;}
  function focusPage(){return `<div class="focus-page"><div class="focus-panel"><p class="eyebrow">STAY PRESENT</p><h1 id="focus-label">${esc(timer.mode)}</h1><p>One thing at a time. You’re right where you need to be.</p><div class="focus-clock" id="focus-clock">${timerText()}</div><div class="focus-progress"><span id="focus-progress" style="width:${(1-timer.remaining/timer.total)*100}%"></span></div><div class="preset-row">${[['Focus',db.settings.focus],['Short break',db.settings.shortBreak],['Long break',db.settings.longBreak]].map(([n,m])=>`<button class="preset ${timer.mode.toLowerCase()===n.toLowerCase()?'active':''}" data-preset="${n}" data-minutes="${m}">${n} · ${m}m</button>`).join('')}<button class="preset" data-custom="1">Custom</button></div><div class="focus-actions"><button class="button primary" id="focus-toggle">${timer.running?'Pause':'Start focus'}</button><button class="button secondary" id="focus-reset">Reset</button><button class="button ghost" onclick="location.hash='#music'">♫ Music</button></div><p style="margin-top:21px;color:#777;font-size:9px">${db.sessions.filter(x=>x.date===today).length} focus sessions today · ${db.sessions.filter(x=>x.date===today).reduce((s,x)=>s+x.minutes,0)} minutes tracked</p></div><div class="page-grid" style="margin-top:14px"><div class="card full"><div class="card-heading"><h2>Recent sessions</h2><a class="text-link" href="#analytics">View analytics →</a></div>${db.sessions.slice(-6).reverse().length?db.sessions.slice(-6).reverse().map(x=>`<div class="list-row"><span class="tag green">${x.minutes} min</span><div class="row-main"><strong>${esc(x.mode)} session</strong><small>${fmtDate(x.date)} · ${new Date(x.completedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join(''):empty('No sessions yet','Start a focus session when you are ready.')}</div></div></div>`;}
  const ambientNames=['Rainy Focus','Forest Calm','Ocean Waves','White Noise','Brown Noise','Soft Ambient Tones'];let audioCtx=null,nodes=[],localTracks=[],trackIndex=0;
  function stopAudio(){try{nodes.forEach(n=>{try{n.stop?.();n.disconnect?.()}catch{}});nodes=[];}catch{}if(audioCtx){audioCtx.close().catch(()=>{});audioCtx=null;}if(window.localAudio){window.localAudio.pause();window.localAudio.src='';window.localAudio=null;}db.music.playing=false;save();renderMini();}
  function createNoise(color){const ctx=audioCtx;const size=ctx.sampleRate*2,buffer=ctx.createBuffer(1,size,ctx.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<size;i++){const white=Math.random()*2-1;if(color==='brown'){last=(last+.02*white)/1.02;data[i]=last*3.5;}else if(color==='pink'){last=.97*last+.03*white;data[i]=last*2;}else data[i]=white*.35;}const src=ctx.createBufferSource();src.buffer=buffer;src.loop=true;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=color==='white'?9000:color==='brown'?450:1800;const gain=ctx.createGain();gain.gain.value=0;src.connect(filter);filter.connect(gain);gain.connect(ctx.destination);src.start();gain.gain.setTargetAtTime((db.music.volume/100)*.18,ctx.currentTime,.9);nodes.push(src,gain);}
  function startAmbient(name){stopAudio();db.music.kind='ambient';db.music.track=name;db.music.playing=true;audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(name==='Soft Ambient Tones'){[174.61,220,261.63].forEach((f,i)=>{let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;g.gain.value=0; o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.setTargetAtTime(db.music.volume/100*.055,audioCtx.currentTime+i*.5,2);nodes.push(o,g);});}else createNoise(name==='White Noise'?'white':name==='Brown Noise'?'brown':name==='Forest Calm'?'pink':'pink');save();renderMini();toast(`${name} is playing`);}
  function playMusic(){if(db.music.kind==='local'&&localTracks.length){playLocal(trackIndex);return;}startAmbient(db.music.track||'Rainy Focus');}
  function playLocal(i){if(!localTracks.length)return;stopAudio();trackIndex=(i+localTracks.length)%localTracks.length;const t=localTracks[trackIndex];db.music.kind='local';db.music.track=t.name;const a=new Audio(t.url);window.localAudio=a;a.volume=db.music.volume/100;a.onended=()=>playLocal(trackIndex+1);a.onerror=()=>toast('This audio format could not be played by your browser.',true);a.play().then(()=>{db.music.playing=true;save();renderMini();}).catch(()=>toast('Audio playback was blocked by your browser.',true));}
  function musicPage(){return `${header('Music studio','Your quiet corner for focus sounds and personal audio.')}<div class="music-studio"><div class="card music-hero"><div class="music-cover">♫</div><div class="music-details"><p class="eyebrow">${db.music.playing?'NOW PLAYING':'READY WHEN YOU ARE'}</p><h1>${esc(db.music.track||'Rainy Focus')}</h1><p>${db.music.kind==='local'?'Your device · Local audio':`Ambient soundscape · ${db.music.playing?'Playing softly':'Ready to play'}`}<br>Sound is generated in your browser and never uploaded.</p><div class="track-controls"><button class="play-button" id="studio-play">${db.music.playing?'Ⅱ':'▶'}</button><button class="button secondary small" id="studio-stop">■ Stop</button><label style="font-size:9px;color:#888">Volume <input class="volume" id="volume-control" type="range" min="0" max="100" value="${db.music.volume}"></label></div></div></div><section class="card" style="margin-top:13px"><div class="card-heading"><h2>Ambient soundscapes</h2><span class="muted">Generated live · no downloads</span></div><div class="page-grid">${ambientNames.map((n,i)=>`<button class="track-item ${db.music.track===n?'active':''}" style="text-align:left" data-sound="${n}"><span class="track-num">${['☂','♧','≈','∿','〰','✧'][i]}</span><div class="row-main"><strong>${n}</strong><small>${['Steady rain for deep work','Soft nature inspired noise','Gentle ocean colored noise','Even full spectrum noise','Warm low frequency hum','Layered soft tone bed'][i]}</small></div>${db.music.track===n&&db.music.playing?'◖':'▷'}</button>`).join('')}</div></section><section class="card" style="margin-top:13px"><div class="card-heading"><h2>My music</h2><button class="button secondary small" id="choose-audio">＋ Add audio files</button></div><p class="muted" style="font-size:10px">Audio stays on your device. Files are not uploaded. Track URLs are held only for this browser session.</p>${localTracks.length?localTracks.map((t,i)=>`<button class="track-item ${db.music.kind==='local'&&trackIndex===i?'active':''}" style="width:100%;text-align:left" data-local-track="${i}"><span class="track-num">${i+1}</span><div class="row-main"><strong>${esc(t.name)}</strong><small>Local audio file</small></div>${db.music.kind==='local'&&trackIndex===i&&db.music.playing?'◖':'▷'}</button>`).join(''):empty('Your playlist is empty','Select audio files from this device to play them here.')}</section></div>`;}
  function notesPage(){return `${header('Notes & resources','Keep useful ideas, links, and study notes close at hand.',addBtn('note','＋ New note'))}<div class="toolbar"><input id="note-search" class="field" placeholder="Search notes…"><select id="note-subject-filter" class="field"><option value="">All subjects</option>${[...new Set(db.notes.map(x=>x.subject).filter(Boolean))].map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div id="notes-grid" class="page-grid">${notesGrid()}</div>`;}
  function notesGrid(){let q=($('#note-search')?.value||'').toLowerCase(),s=$('#note-subject-filter')?.value||'';let items=db.notes.filter(n=>(!q||`${n.title} ${n.content} ${n.tags}`.toLowerCase().includes(q))&&(!s||n.subject===s));return items.length?items.map(n=>`<article class="card note-card"><div class="card-heading"><span class="tag">${esc(n.subject||'General')}</span><div><button class="icon-button" data-edit="note" data-id="${n.id}">✎</button><button class="icon-button danger" data-delete="note" data-id="${n.id}">×</button></div></div><h3>${esc(n.title)} ${n.pinned?'✦':''}</h3><p>${esc((n.content||'').slice(0,180))}${(n.content||'').length>180?'…':''}</p>${n.url?`<a href="${safeUrl(n.url)}" target="_blank" rel="noopener noreferrer" class="text-link">Open resource ↗</a>`:''}<div class="note-meta">${esc(n.topic||'')} · Updated ${fmtDate(n.updated||n.created)}</div></article>`).join(''):empty('No notes found','Create a note to collect your study resources.',addBtn('note','＋ New note'));}
  function safeUrl(x){try{const u=new URL(x);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}}
  function journalPage(){let entry=db.journals.find(x=>x.date===today);return `${header('Daily journal','A small reflection can turn effort into momentum.',addBtn('journal',entry?'✎ Edit today':'＋ Write today'))}<div class="page-grid"><section class="card"><div class="card-heading"><h2>Today · ${fmtDate(today,{weekday:'long',month:'long',day:'numeric'})}</h2><span class="tag">${entry?`Mood ${entry.mood||'—'}`:'A fresh page'}</span></div>${entry?`<div class="journal-view">${[['What I studied',entry.studied],['What I completed',entry.completed],['What I found difficult',entry.difficult],['What I need to improve',entry.improve],['Plan for tomorrow',entry.tomorrow]].map(([l,v])=>`<div class="settings-row"><div><strong>${l}</strong><small>${esc(v||'—')}</small></div></div>`).join('')}</div>`:empty('Take a moment to reflect','What went well? What is one thing you want to understand better?',addBtn('journal','＋ Write today'))}</section><section class="card"><div class="card-heading"><h2>Recent entries</h2></div>${db.journals.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,7).map(x=>`<div class="list-row"><div class="row-main"><strong>${fmtDate(x.date,{weekday:'short',month:'short',day:'numeric'})}</strong><small>${esc((x.studied||x.completed||'No reflection yet').slice(0,75))}</small></div><button class="icon-button" data-edit="journal" data-id="${x.id}">✎</button></div>`).join('')||empty('No past entries','Your reflections will show here.')}</section></div>`;}
  function analyticsPage(){const last7=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const key=dateKey(d);return{key,label:d.toLocaleDateString(undefined,{weekday:'short'}),mins:db.sessions.filter(x=>x.date===key).reduce((s,x)=>s+x.minutes,0)}});const max=Math.max(30,...last7.map(x=>x.mins));const total=db.sessions.reduce((s,x)=>s+x.minutes,0),complete=db.tasks.filter(x=>x.status==='Completed').length,taskRate=db.tasks.length?Math.round(complete/db.tasks.length*100):0;const subjects={};db.sessions.forEach(x=>subjects[x.subject||'General']=(subjects[x.subject||'General']||0)+x.minutes);return `${header('Analytics','Your progress, built from your real study sessions and records.')}<div class="page-grid"><section class="card full"><div class="card-heading"><h2>Study time · last 7 days</h2><span class="tag">${last7.reduce((s,x)=>s+x.mins,0)} min tracked</span></div><div class="chart">${last7.map(x=>`<div class="chart-col"><div class="chart-bar" title="${x.mins} min" style="height:${Math.max(3,x.mins/max*100)}%"></div><span class="chart-label">${x.label}</span></div>`).join('')}</div><div style="height:21px"></div></section><div class="card stat"><div class="stat-top">Total focus time <span class="stat-icon">◷</span></div><strong>${Math.floor(total/60)}h ${total%60}m</strong><small>Across ${db.sessions.length} sessions</small></div><div class="card stat"><div class="stat-top">Task completion <span class="stat-icon">☷</span></div><strong>${taskRate}%</strong><small>${complete} of ${db.tasks.length} tasks</small></div><div class="card stat"><div class="stat-top">Goals completed <span class="stat-icon">◎</span></div><strong>${db.goals.filter(x=>x.status==='Completed').length}</strong><small>Of ${db.goals.length} total goals</small></div><div class="card stat"><div class="stat-top">Current streak <span class="stat-icon">♨</span></div><strong>${db.streak||0} days</strong><small>Come back tomorrow to keep it going</small></div><section class="card full"><div class="card-heading"><h2>Study activity</h2><span class="muted">Last 56 days</span></div><div class="heatmap">${Array.from({length:56},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(55-i));const k=dateKey(d),m=db.sessions.filter(x=>x.date===k).reduce((s,x)=>s+x.minutes,0),v=m===0?0:m<30?1:m<75?2:3;return `<div class="heat" data-v="${v}" title="${fmtDate(k)} · ${m} min"></div>`}).join('')}</div></section><section class="card"><div class="card-heading"><h2>Active backlogs</h2></div>${db.backlogs.length?db.backlogs.map(x=>`<div class="list-row"><div class="row-main"><strong>${esc(x.subject)} · ${esc(x.topic)}</strong><small>${x.progress||0}% complete</small><div class="task-meter"><span style="width:${x.progress||0}%"></span></div></div></div>`).join(''):empty('No backlog data','Backlog progress will appear as you add items.')}</section><section class="card"><div class="card-heading"><h2>Revision consistency</h2></div>${db.revisions.length?`<strong style="font:700 24px var(--display)">${db.revisions.filter(x=>x.lastReviewed).length}</strong><span class="muted" style="font-size:10px"> of ${db.revisions.length} topics reviewed at least once</span>`:empty('No revision data','Start a revision plan to build consistency.')}</section></div>`;}
  function settingsPage(){return `${header('Settings','Make Study OS fit the way you study.')}<div class="page-grid"><section class="card"><div class="card-heading"><h2>Study preferences</h2></div>${setting('Display name','Your name appears in the dashboard greeting.','name',db.settings.name,'text')}${setting('Daily study target','Hours you want to study each day.','target',db.settings.target,'number')}${setting('Focus session','Default Pomodoro focus duration in minutes.','focus',db.settings.focus,'number')}${setting('Short break','Short break length in minutes.','shortBreak',db.settings.shortBreak,'number')}${setting('Long break','Long break length in minutes.','longBreak',db.settings.longBreak,'number')}<div class="settings-row"><div><strong>Sound notifications</strong><small>Play a soft chime when a timer ends.</small></div><input class="switch" type="checkbox" id="notify-setting" ${db.settings.notifications?'checked':''}></div><button class="button primary" id="save-settings" style="margin-top:12px">Save preferences</button></section><section class="card"><div class="card-heading"><h2>Subjects</h2></div><p class="muted" style="font-size:10px">Add subjects to use them in goals, tasks, and revision topics.</p><div class="toolbar"><input class="field" id="subject-input" placeholder="e.g. Mathematics"><button class="button secondary" id="add-subject">Add subject</button></div><div>${(db.settings.subjects||[]).map(x=>`<span class="tag" style="margin:3px">${esc(x)} <button data-remove-subject="${esc(x)}" style="background:none;border:0;color:#bbb">×</button></span>`).join('')||'<span class="muted" style="font-size:10px">No subjects added yet.</span>'}</div><div class="settings-row" style="margin-top:16px"><div><strong>Keyboard shortcuts</strong><small>⌘/Ctrl + K opens search · F starts focus</small></div></div></section></div>`;}
  function setting(label,desc,key,val,type){return `<label class="settings-row"><div><strong>${label}</strong><small>${desc}</small></div><input class="field setting-input" data-setting="${key}" type="${type}" value="${esc(val)}" ${type==='number'?'min="1" max="720" style="width:80px"':'style="width:145px"'}></label>`;}
  function dataPage(){return `${header('Data & sync','Your records are stored on this device. Export a backup any time.')}<div class="page-grid"><section class="card"><div class="card-heading"><h2>Local storage</h2><span class="tag green">On this device</span></div><p class="muted" style="font-size:10px;line-height:1.7">Study OS saves your goals, sessions, notes, and preferences in this browser. Data stays here unless you export it. Clearing browser storage will remove your records.</p><div class="settings-row"><div><strong>Cloud sync</strong><small>No cloud backend is configured for this project.</small></div><span class="status-pill">Not connected</span></div></section><section class="card"><div class="card-heading"><h2>Back up your data</h2></div><p class="muted" style="font-size:10px">Export a JSON backup or import one from another device.</p><div class="toolbar"><button class="button primary" id="export-data">↓ Export JSON</button><button class="button secondary" id="import-data">↑ Import backup</button></div></section><section class="card full"><div class="card-heading"><h2>Reset study data</h2></div><p class="muted" style="font-size:10px">Remove all locally stored goals, tasks, notes, and settings. This cannot be undone.</p><button class="button" id="reset-data" style="border-color:#713838;color:#f49797">Reset all data…</button></section></div>`;}
  function reportPage(){return `${header('Report an issue','Found a bug or something that could work better? Send me a note.')}<div class="page-grid"><section class="card issue-form"><div class="card-heading"><h2>Tell me what happened</h2><span class="tag">Goes to Somesh</span></div><p class="muted" style="font-size:10px;line-height:1.7">This opens your email app with the report details filled in. Your message is sent directly to <a href="mailto:somesh.edu7@gmail.com" class="text-link">somesh.edu7@gmail.com</a>.</p><form id="issue-form"><label class="form-item">Your name <input class="field" name="reporter" placeholder="Name (optional)"></label><label class="form-item">What went wrong? <input class="field" name="title" required placeholder="Short summary"></label><label class="form-item">Details <textarea class="field" name="details" required rows="6" placeholder="What did you expect, and what happened instead?"></textarea></label><button class="button primary" type="submit">Prepare email ↗</button></form></section><section class="card"><div class="card-heading"><h2>Before you send</h2></div><div class="settings-row"><div><strong>Include the page</strong><small>Tell me which Study OS page you were using.</small></div></div><div class="settings-row"><div><strong>Steps to reproduce</strong><small>List what you clicked so I can find the issue.</small></div></div><div class="settings-row"><div><strong>What you expected</strong><small>A short description helps me understand the problem.</small></div></div><p class="muted" style="font-size:9px;line-height:1.6">This app does not send reports to a server. Your email app will ask you to review and send the message.</p></section></div>`;}
  function developerPage(){return `${header('Developer’s insight','A little about the person building Study OS.')}<section class="card full"><p class="eyebrow">WHY I’M BUILDING THIS</p><blockquote class="dev-quote">“I’ve often felt underestimated. Instead of letting that decide what I can do, I’m building something useful, one step at a time. Study OS is my way of turning that feeling into focus, persistence, and a product I’m proud to keep improving. A setback isn’t the end of the story.”</blockquote><p class="dev-credit">— Somesh Bali · Creator of Study OS</p><div class="settings-row" style="margin-top:20px"><div><strong>Still building</strong><small>Study OS is a personal project, shaped by learning, feedback, and steady work.</small></div><a class="button secondary small" href="#report">Share feedback</a></div></section>`;}
  function render(){const target=$('#content');if(!target)return;const views={dashboard,goals:goalsPage,tasks:tasksPage,timetable:timetablePage,revision:revisionPage,exams:examsPage,focus:focusPage,music:musicPage,notes:notesPage,journal:journalPage,analytics:analyticsPage,settings:settingsPage,data:dataPage,report:reportPage,developer:developerPage};target.innerHTML=views[currentPage]();updateClock();renderMini();}
  function renderMini(){const el=$('#mini-player');if(!el)return;el.classList.toggle('playing',db.music.playing);$('#mini-title').textContent=db.music.track||'Rainy Focus';$('#mini-subtitle').textContent=db.music.kind==='local'?'Your music library':db.music.playing?'Ambient soundscape · Playing':'Ambient soundscape';$('#mini-toggle').textContent=db.music.playing?'Ⅱ':'▶';}
  const subjects=()=>db.settings.subjects||[];
  const input=(label,name,type='text',value='',required=false,options=null,full=false)=>`<div class="form-item ${full?'full':''}"><label for="f-${name}">${label}${required?' *':''}</label>${options?`<select class="field" id="f-${name}" name="${name}" ${required?'required':''}>${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea class="field" id="f-${name}" name="${name}" ${required?'required':''}>${esc(value)}</textarea>`:`<input class="field" id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}>`}</div>`;
  const subjectOptions=()=>['',...subjects()];
  function fields(type,item={}){const sub=subjectOptions(),priority=['Low','Medium','High'];switch(type){case'goal':return input('Goal title','title','text',item.title,true)+input('Subject','subject','text',item.subject||'',false)+input('Chapter or topic','topic','text',item.topic||'')+input('Planned date','date','date',item.date||today,true)+input('Target duration (minutes)','duration','number',item.duration||45)+input('Priority','priority','text',item.priority||'Medium',false,priority)+input('Status','status','text',item.status||'Not Started',false,['Not Started','In Progress','Completed'])+input('Description','description','textarea',item.description||'',false,null,true)+input('Notes','notes','textarea',item.notes||'',false,null,true);
    case'task':return input('Task title','title','text',item.title,true)+input('Subject','subject','text',item.subject||'')+input('Category','category','text',item.category||'Homework',true,['Homework','Assignments','Lectures','Practice Questions','Revision','Projects','Other'])+input('Due date','due','date',item.due||today)+input('Priority','priority','text',item.priority||'Medium',true,priority)+input('Estimated duration (minutes)','estimate','number',item.estimate||30)+input('Status','status','text',item.status||'To Do',true,['To Do','In Progress','Completed','Deferred'])+input('Description','description','textarea',item.description||'',false,null,true);
    case'backlog':return input('Subject','subject','text',item.subject||'',true)+input('Chapter or topic','topic','text',item.topic||'',true)+input('Type','type','text',item.type||'Chapter',true,['Lecture','Chapter','Homework','Practice','Revision'])+input('Pending lectures','lectures','number',item.lectures||0)+input('Estimated hours','hours','number',item.hours||2)+input('Priority','priority','text',item.priority||'Medium',true,priority)+input('Target completion date','due','date',item.due||'')+input('Progress (%)','progress','number',item.progress||0)+input('Reason','reason','text',item.reason||'',false,null,true);
    case'event':return input('Title','title','text',item.title||'',true)+input('Subject','subject','text',item.subject||'')+input('Day','day','text',item.day||dayName,true,['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'])+input('Start time','start','time',item.start||'09:00',true)+input('End time','end','time',item.end||'10:00',true)+input('Activity type','type','text',item.type||'Self-study',true,['School','Coaching','Self-study','Break','Other'])+input('Location','location','text',item.location||'')+input('Notes','notes','text',item.notes||'');
    case'revision':return input('Subject','subject','text',item.subject||'',true)+input('Chapter or topic','topic','text',item.topic||'',true)+input('Date last studied','lastStudied','date',item.lastStudied||today,true)+input('Next revision date','nextDate','date',item.nextDate||today,true)+input('Interval (days)','interval','number',item.interval||3)+input('Difficulty (1–5)','difficulty','number',item.difficulty||3)+input('Notes','notes','textarea',item.notes||'',false,null,true);
    case'exam':return input('Exam name','name','text',item.name||'',true)+input('Subject or category','subject','text',item.subject||'',true)+input('Exam date','date','date',item.date||'',true)+input('Exam time','time','time',item.time||'')+input('Syllabus topics (comma-separated)','topics','textarea',item.topics||'',false,null,true)+input('Preparation notes','notes','textarea',item.notes||'',false,null,true);
    case'note':return input('Title','title','text',item.title||'',true)+input('Subject','subject','text',item.subject||'')+input('Chapter or topic','topic','text',item.topic||'')+input('Tags (comma-separated)','tags','text',item.tags||'')+input('Note content','content','textarea',item.content||'',false,null,true)+input('Resource link (optional)','url','url',item.url||'',false,null,true)+`<label class="form-item"><span><input type="checkbox" name="pinned" ${item.pinned?'checked':''}> Pin this note</span></label>`;
    case'journal':return input('Date','date','date',item.date||today,true)+input('Mood or energy (1–5)','mood','number',item.mood||'')+input('What I studied','studied','textarea',item.studied||'',false,null,true)+input('What I completed','completed','textarea',item.completed||'',false,null,true)+input('What I found difficult','difficult','textarea',item.difficult||'',false,null,true)+input('What I need to improve','improve','textarea',item.improve||'',false,null,true)+input('Plan for tomorrow','tomorrow','textarea',item.tomorrow||'',false,null,true);
  }}
  const entityKey={goal:'goals',task:'tasks',backlog:'backlogs',event:'events',revision:'revisions',exam:'exams',note:'notes',journal:'journals'};
  function openAdd(type,item=null){if(!entityKey[type])return;$('#modal-title').textContent=item?`Edit ${type}`:`Add ${type==='event'?'timetable session':type}`;$('#modal-eyebrow').textContent=item?'EDIT RECORD':'QUICK ADD';$('#modal-fields').innerHTML=`<div class="form-grid">${fields(type,item||{})}</div>`;$('#modal-form').dataset.type=type;$('#modal-form').dataset.id=item?.id||'';$('#modal').showModal();}
  function formObject(form){let o={};new FormData(form).forEach((v,k)=>o[k]=String(v).trim());const pin=form.querySelector('[name=pinned]');if(pin)o.pinned=pin.checked;return o;}
  function validate(type,o){if(type==='event'&&o.end<=o.start){toast('End time must be later than start time.',true);return false;}if(type==='exam'&&o.date<today){toast('Choose an upcoming exam date.',true);return false;}if(type==='note'&&o.url){try{let u=new URL(o.url);if(!['https:','http:'].includes(u.protocol))throw 0;}catch{toast('Enter a valid http or https resource URL.',true);return false;}}return true;}
  $('#modal-form').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const type=e.currentTarget.dataset.type,key=entityKey[type],id=e.currentTarget.dataset.id;const data=formObject(e.currentTarget);if(!validate(type,data))return;data.id=id||uid();if(type==='note'){data.created=id?(db.notes.find(x=>x.id===id)?.created||today):today;data.updated=today;}if(type==='journal'){if(db.journals.some(x=>x.date===data.date&&x.id!==id)){toast('There is already an entry for this date. Edit that entry instead.',true);return;}}
    if(type==='event'){const conflict=db.events.find(x=>x.day===data.day&&x.id!==id&&data.start<x.end&&data.end>x.start);if(conflict&&!confirm(`This overlaps with “${conflict.title}”. Save anyway?`))return;}
    if(id){const i=db[key].findIndex(x=>x.id===id);if(i>=0)db[key][i]={...db[key][i],...data};}else db[key].push(data);if(type==='revision'&&!id)data.lastReviewed='';save();$('#modal').close();toast(id?'Changes saved':'Added successfully');render();});
  function remove(type,id){let key=entityKey[type];if(!key)return;const x=db[key].find(x=>x.id===id);if(!confirm(`Delete ${x?.title||x?.topic||x?.name||'this item'}?`))return;db[key]=db[key].filter(x=>x.id!==id);save();toast('Deleted');render();}
  function toggle(type,id){const key=entityKey[type],x=db[key]?.find(x=>x.id===id);if(!x)return;if(type==='revision'){x.lastReviewed=today;x.lastStudied=today;x.nextDate=dateKey(new Date(Date.now()+Number(x.interval||3)*86400000));}else if(type==='task')x.status=x.status==='Completed'?'To Do':'Completed';else if(type==='goal')x.status=x.status==='Completed'?'In Progress':'Completed';save();render();}
  function quickMenu(){const choices=[['goal','Daily goal'],['task','Task'],['backlog','Backlog item'],['event','Timetable session'],['revision','Revision topic'],['exam','Exam'],['note','Note'],['journal','Journal entry']];const opt=prompt(`Quick add — choose a number:\n${choices.map((x,i)=>`${i+1}. ${x[1]}`).join('\n')}`);let n=Number(opt)-1;if(Number.isInteger(n)&&choices[n])openAdd(choices[n][0]);}
  function openSearch(){const d=$('#search-dialog');d.showModal();$('#global-search').value='';searchRender('');setTimeout(()=>$('#global-search').focus(),20);}
  function searchRender(query){const q=query.toLowerCase().trim(),all=[];for(const [type,key] of [['Goal','goals'],['Task','tasks'],['Backlog','backlogs'],['Note','notes'],['Exam','exams'],['Journal','journals']])db[key].forEach(x=>{const title=x.title||x.topic||x.name||'Journal entry',body=x.content||x.description||x.studied||'';if(!q||`${title} ${body} ${x.subject||''}`.toLowerCase().includes(q))all.push({type,title,body,id:x.id});});$('#search-results').innerHTML=all.length?all.slice(0,20).map(x=>`<button class="search-result" data-search-type="${x.type.toLowerCase()}" data-id="${x.id}">${esc(x.title)}<small>${x.type} · ${esc(x.body.slice(0,70))}</small></button>`).join(''):empty('No results','Try a different search term.');}
  // Event delegation keeps each rendered page compact and functional.
  document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.dataset.add){openAdd(t.dataset.add);return;}if(t.dataset.delete){remove(t.dataset.delete,t.dataset.id);return;}if(t.dataset.toggle){toggle(t.dataset.toggle,t.dataset.id);return;}if(t.dataset.edit){const type=t.dataset.edit,key=entityKey[type],x=db[key]?.find(y=>y.id===t.dataset.id);if(x)openAdd(type,x);return;}if(t.dataset.preset){setPreset(t.dataset.preset,Number(t.dataset.minutes));return;}if(t.dataset.custom){const m=Number(prompt('Custom timer length in minutes (1–180):','40'));if(Number.isFinite(m)&&m>=1&&m<=180)setPreset('Custom focus',m);else if(m)toast('Enter a duration from 1 to 180 minutes.',true);return;}if(t.id==='timer-main'||t.id==='focus-toggle'){timer.running?pauseTimer():startTimer();return;}if(t.id==='timer-reset'||t.id==='focus-reset'){resetTimer();return;}if(t.id==='dash-music'||t.id==='mini-toggle'){db.music.playing?stopAudio():playMusic();return;}if(t.id==='mini-play'){location.hash='#music';return;}if(t.id==='mini-stop'||t.id==='studio-stop'){stopAudio();toast('Playback stopped');return;}if(t.id==='studio-play'){db.music.playing?stopAudio():playMusic();return;}if(t.dataset.sound){startAmbient(t.dataset.sound);render();return;}if(t.id==='choose-audio')$('#audio-file').click();if(t.id==='search-open')openSearch();if(t.id==='quick-add')quickMenu();if(t.id==='mobile-menu')$('#sidebar').classList.toggle('open');if(t.dataset.day){$$('.day-chip').forEach(x=>x.classList.toggle('active',x===t));$('#agenda').innerHTML=agenda(t.dataset.day);return;}if(t.dataset.localTrack!=null)playLocal(Number(t.dataset.localTrack));if(t.id==='add-subject'){const i=$('#subject-input'),v=i.value.trim();if(v&&!subjects().includes(v)){db.settings.subjects.push(v);save();render();}return;}if(t.dataset.removeSubject!=null){db.settings.subjects=db.settings.subjects.filter(x=>x!==t.dataset.removeSubject);save();render();return;}if(t.id==='break-backlog'){const b=db.backlogs.find(x=>x.id===$('#backlog-select').value);if(!b){toast('Choose a backlog item first.',true);return;}let n=Math.min(20,Math.max(1,Number($('#break-parts').value)||1));for(let i=0;i<n;i++)db.goals.push({id:uid(),title:`${b.topic} · Part ${i+1}`,subject:b.subject,topic:b.topic,date:today,duration:Math.round((Number(b.hours)||1)*60/n),priority:b.priority,status:'Not Started',notes:'Created from backlog breakdown'});save();toast(`${n} goals created`);render();return;}if(t.dataset.convert){const b=db.backlogs.find(x=>x.id===t.dataset.convert);openAdd('goal',{title:`Work on ${b.topic}`,subject:b.subject,topic:b.topic,date:today,duration:Math.round((Number(b.hours)||1)*60),priority:b.priority});return;}if(t.dataset.suggest){const item=db[entityKey[t.dataset.suggest]]?.find(x=>x.id===t.dataset.id);if(item){if(t.dataset.suggest==='task')db.goals.push({id:uid(),title:item.title,subject:item.subject,date:today,duration:item.estimate||30,priority:item.priority,status:'Not Started',notes:'Suggested from tasks'});else db.goals.push({id:uid(),title:t.dataset.suggest==='revision'?`Revise ${item.topic}`:`Work on ${item.topic}`,subject:item.subject,topic:item.topic,date:today,duration:30,priority:item.priority,status:'Not Started'});save();toast('Added to today’s goals');render();}return;}if(t.id==='export-data'){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),data:db},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`study-os-backup-${today}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup exported');return;}if(t.id==='import-data')$('#import-file').click();if(t.id==='reset-data'){if(confirm('Permanently delete all Study OS data from this browser?')){localStorage.removeItem(KEY);location.reload();}return;}if(t.id==='save-settings'){const vals={};$$('[data-setting]').forEach(i=>vals[i.dataset.setting]=i.type==='number'?Number(i.value):i.value);db.settings={...db.settings,...vals,notifications:$('#notify-setting').checked};save();if(db.settings.notifications&&'Notification'in window&&Notification.permission==='default')Notification.requestPermission();toast('Preferences saved');render();return;}if(t.dataset.searchType){$('#search-dialog').close();const map={goal:'goals',task:'tasks',backlog:'tasks',note:'notes',exam:'exams',journal:'journal'};location.hash='#'+map[t.dataset.searchType];return;}});
  document.addEventListener('change',e=>{const t=e.target;if(t.id==='task-filter'){const el=$('#task-list');if(el)el.innerHTML=taskTable();}if(t.classList.contains('task-status')){const x=db.tasks.find(x=>x.id===t.dataset.id);if(x){x.status=t.value;save();render();}}if(t.classList.contains('backlog-progress')){const x=db.backlogs.find(x=>x.id===t.dataset.id);if(x){x.progress=Math.max(0,Math.min(100,Number(t.value)));save();render();}}if(t.id==='volume-control'){db.music.volume=Number(t.value);if(audioCtx)nodes.filter(n=>n.gain).forEach(n=>n.gain.setTargetAtTime(db.music.volume/100*.18,audioCtx.currentTime,.2));if(window.localAudio)window.localAudio.volume=db.music.volume/100;save();}if(t.dataset.examTopic){const x=db.exams.find(x=>x.id===t.dataset.examTopic);if(x){x.doneTopics=x.doneTopics||[];if(t.checked&&!x.doneTopics.includes(t.dataset.topic))x.doneTopics.push(t.dataset.topic);else x.doneTopics=x.doneTopics.filter(q=>q!==t.dataset.topic);save();render();}}if(['goal-filter','goal-date-filter','goal-sort'].includes(t.id)){const el=$('#content');let items=db.goals.filter(x=>(!$('#goal-date-filter')?.value||x.date===$('#goal-date-filter').value)&&(!$('#goal-filter')?.value||x.status===$('#goal-filter').value));const sort=$('#goal-sort')?.value;if(sort==='priority'){const p={High:0,Medium:1,Low:2};items.sort((a,b)=>(p[a.priority]??1)-(p[b.priority]??1));}else if(sort==='created')items.sort((a,b)=>b.id.localeCompare(a.id));else items.sort((a,b)=>(a.date||'').localeCompare(b.date||''));const target=el.querySelector('.card');if(target)target.innerHTML=rows(items,'goal','No goals match this view');}if(t.id==='note-subject-filter'){const el=$('#notes-grid');if(el)el.innerHTML=notesGrid();}});
  document.addEventListener('input',e=>{if(e.target.id==='global-search')searchRender(e.target.value);if(e.target.id==='note-search'){const el=$('#notes-grid');if(el)el.innerHTML=notesGrid();}});
  document.addEventListener('submit',e=>{if(e.target.id!=='issue-form')return;e.preventDefault();const f=new FormData(e.target),subject=String(f.get('title')||'Study OS issue').trim(),name=String(f.get('reporter')||'Not provided').trim(),details=String(f.get('details')||'').trim();const body=`Issue: ${subject}\n\nReported by: ${name}\nPage: ${pageNames[currentPage]}\n\nDetails:\n${details}`;window.location.href=`mailto:somesh.edu7@gmail.com?${new URLSearchParams({subject:`Study OS issue: ${subject}`,body})}`;});
  $('#audio-file').addEventListener('change',e=>{[...e.target.files].forEach(file=>{if(!file.type.startsWith('audio/')){toast(`${file.name} is not a supported audio file.`,true);return;}localTracks.push({name:file.name.replace(/\.[^.]+$/,''),url:URL.createObjectURL(file)});});if(localTracks.length){toast(`${e.target.files.length} track(s) added`);if(currentPage==='music')render();}e.target.value='';});
  window.addEventListener('pagehide',()=>{try{nodes.forEach(n=>{try{n.stop?.();n.disconnect?.()}catch{}});localTracks.forEach(t=>URL.revokeObjectURL(t.url));}catch{}});
  $('#import-file').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const parsed=JSON.parse(r.result);const incoming=parsed.data||parsed;if(!incoming||!Array.isArray(incoming.goals)||!Array.isArray(incoming.tasks))throw 0;if(!confirm('Import this backup and replace the data currently in this browser?'))return;db={...blank(),...incoming,settings:{...blank().settings,...incoming.settings},music:{...blank().music,...incoming.music}};save();toast('Backup imported');render();}catch{toast('This file is not a valid Study OS backup.',true);}};r.readAsText(f);e.target.value='';});
  window.addEventListener('hashchange',route);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape'){$('#sidebar').classList.remove('open');}if(e.key.toLowerCase()==='f'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open&&!$('#search-dialog').open){if(currentPage!=='focus')location.hash='#focus';if(!timer.running)startTimer();}});
  $('#search-open').addEventListener('click',openSearch);
  document.addEventListener('click',e=>{if(e.target.id==='break-backlog')return;});
  $('#today-label').textContent=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric'});
  syncProfile();route();
  // Recover an in-progress timer after refresh using its persisted wall-clock deadline.
  try{const t=JSON.parse(sessionStorage.getItem('study-os-timer')||'null');if(t&&t.running&&t.endAt>Date.now()){timer={...timer,...t,running:true};timer.interval=setInterval(tick,250);}else if(t&&t.remaining>0){timer.remaining=t.remaining;timer.total=t.total;timer.mode=t.mode;}}catch{}
  setInterval(()=>{if(timer.running){sessionStorage.setItem('study-os-timer',JSON.stringify({running:timer.running,endAt:timer.endAt,remaining:timer.remaining,total:timer.total,mode:timer.mode}));tick();}},1000);
})();
